import{_ as r,B as s,o as c,c as l,a8 as d,a as o,E as n,f as t}from"./chunks/framework.CNIpabDg.js";const k=JSON.parse('{"title":"Time","description":"Separate monotonic elapsed time and adjustable UTC, including synchronization and WASI clock semantics.","frontmatter":{"layout":"doc","docType":"explanation","description":"Separate monotonic elapsed time and adjustable UTC, including synchronization and WASI clock semantics."},"headers":[],"relativePath":"explanation/architecture/subsystems/time.md","filePath":"explanation/architecture/subsystems/time.md","lastUpdated":1793018472000}'),m={name:"explanation/architecture/subsystems/time.md"};function u(p,e,h,g,b,f){const a=s("CodeReference"),i=s("HostReference");return c(),l("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793018472000"},[e[10]||(e[10]=d('<h1 id="time" tabindex="-1">Time <a class="header-anchor" href="#time" aria-label="Permalink to &quot;Time&quot;">​</a></h1><p>Xila&#39;s Time subsystem has <strong>two distinct clocks</strong> following Core #533 and #534. The monotonic clock measures elapsed time and powers deadlines; the system&#39;s signed UTC clock represents civil time and may be explicitly corrected. This separation prevents NTP, manual or RTC corrections from changing uptime, LVGL animation ticks, TCP/ICMP timers or WASI monotonic subscriptions.</p><h2 id="monotonic-clock" tabindex="-1">Monotonic clock <a class="header-anchor" href="#monotonic-clock" aria-label="Permalink to &quot;Monotonic clock&quot;">​</a></h2><p><code>time::Manager::monotonic_now()</code> returns <code>Duration</code> since a platform-defined arbitrary epoch. <code>uptime()</code> measures time since manager construction. <code>monotonic_resolution()</code> reports the source&#39;s nominal resolution and <code>monotonic_milliseconds_wrapping()</code> supplies a wrapping u32 clock for LVGL (wrap approximately every 49.7 days). Monotonic timestamps do not encode calendar time and <strong>must not be persisted between reboots</strong>.</p><p>The default <code>EmbassyClock</code> shares the executor&#39;s monotonic tick source with task timers and guest deadlines. Native uses an Instant-backed driver; the browser uses <code>performance.now()</code> through Embassy. The resolution is nominal, not a guarantee of physical clock accuracy. On microcontrollers, low-power sleep may pause ticks and deep sleep/reboot starts a new epoch.</p><p>A platform can inject a custom <code>MonotonicClock</code> if it is nondecreasing and compatible with the executor&#39;s timebase.</p><h2 id="signed-utc-and-synchronization" tabindex="-1">Signed UTC and synchronization <a class="header-anchor" href="#signed-utc-and-synchronization" aria-label="Permalink to &quot;Signed UTC and synchronization&quot;">​</a></h2><p><code>realtime_now()</code> returns a signed <code>Timestamp</code> (Unix nanoseconds stored as <code>i128</code>) or an error while unsynchronized or if arithmetic overflows. The time manager derives UTC by applying a checked signed correction to monotonically advancing time, rather than reading a device for every query.</p><ul><li><code>Manager::new(source)</code> initializes from a trusted <code>RealtimeSource</code> sample. Native and browser bootstraps read the host clock once.</li><li><code>Manager::unsynchronized()</code> (or <code>with_clock(custom_clock)</code>) allows booting without a trustworthy RTC. The elapsed clock remains usable immediately.</li><li><code>synchronize(source)</code> reads a trusted epoch and records its provenance. <code>set_realtime</code> accepts an explicit UTC setting; source invalidation makes UTC unreadable until resynchronized.</li><li>Synchronization metadata contains the source kind, application instant, nominal resolution and source-reported accuracy. It is <strong>not</strong> a continuously maintained accuracy guarantee.</li></ul><p>Corrections <strong>step immediately</strong>, forward or backward, and failed corrections preserve the old state. No gradual slew, timezone database, daylight-saving conversion, automatic synchronization protocol or persistence across reboot is implemented. Those must be provided at a higher layer.</p><h2 id="effects-on-other-subsystems" tabindex="-1">Effects on other subsystems <a class="header-anchor" href="#effects-on-other-subsystems" aria-label="Permalink to &quot;Effects on other subsystems&quot;">​</a></h2><ul><li><strong>Graphics</strong>: LVGL tick scheduling and shell/Settings periodic refresh use monotonic time.</li><li><strong>Network</strong>: smoltcp and ICMP timeouts/RTT use monotonic instants; UTC changes cannot alter their deadlines.</li><li><strong>WASI</strong>: realtime clock reads require valid UTC and return a WASI error if invalid/out of range. Monotonic <code>poll_oneoff</code> subscriptions still function when UTC is unsynchronized or broken, and the host reads only the clocks actually subscribed.</li><li><strong>VFS</strong>: timestamps use UTC where available; existing authorized file access remains possible if UTC is invalid. Creating entries requiring a new timestamp can fail until UTC is available. Corrected UTC may legitimately move backwards.</li><li><strong>Shell</strong>: unavailable UTC displays <code>--:--</code> instead of a bogus clock.</li></ul><h2 id="construction-and-ownership" tabindex="-1">Construction and ownership <a class="header-anchor" href="#construction-and-ownership" aria-label="Permalink to &quot;Construction and ownership&quot;">​</a></h2><p>A final runtime owns its Time manager and passes references to clients; it is not a process-global singleton. State changes and reads use short synchronization critical sections, with no allocation or I/O while holding the lock. Custom monotonic sources must be safe to call under that critical section. Clock source trust and persistence are application/platform responsibilities.</p><p>The host implementation measured a 128-byte Time manager on x86_64. This is <strong>not</strong> a total RAM, stack or MCU flash measurement. Host and browser tests cover UTC jumps, invalid UTC, overflow, WASI polling, tick rollover and GUI behavior; ESP32-S3 validation remains unproven because the Xtensa toolchain was unavailable.</p><h2 id="implementation-and-references" tabindex="-1">Implementation and references <a class="header-anchor" href="#implementation-and-references" aria-label="Permalink to &quot;Implementation and references&quot;">​</a></h2>',16)),o("ul",null,[o("li",null,[n(a,{path:"subsystems/time/src/manager.rs"}),e[0]||(e[0]=t(" — ",-1)),e[1]||(e[1]=o("code",null,"Manager",-1)),e[2]||(e[2]=t(", ",-1)),e[3]||(e[3]=o("code",null,"MonotonicClock",-1)),e[4]||(e[4]=t(", ",-1)),e[5]||(e[5]=o("code",null,"EmbassyClock",-1)),e[6]||(e[6]=t(", and synchronization lifecycle.",-1))]),o("li",null,[n(a,{path:"subsystems/time/src/lib.rs"}),e[7]||(e[7]=t(" — public time API exports.",-1))]),o("li",null,[n(i,{crate:"time"}),e[8]||(e[8]=t(" — host Rustdoc.",-1))]),e[9]||(e[9]=o("li",null,[o("a",{href:"/explanation/architecture/subsystems/network.html"},"Network"),t(", "),o("a",{href:"/explanation/architecture/subsystems/virtual_file_system.html"},"VFS"),t(", and "),o("a",{href:"/reference/wasm-runtime.html"},"WASM runtime"),t(" — important consumers.")],-1))])])}const T=r(m,[["render",u]]);export{k as __pageData,T as default};
